const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);return n;};
export function tradeDebugReport(ship,details,world){return JSON.stringify({format:'merchant-trade-debug-v1',ship:{id:ship?.id,type:ship?.type,faction:ship?.faction},ports:(world?.ports??[]).map(p=>({id:p.id,name:p.name})),...details},null,2);}
// IDs nest URI-encoded account and order identities. Decode only their display
// text; settlement/debug records retain their exact authoritative identifiers.
export function readableEconomicId(value){let text=String(value??'');for(let i=0;i<4;i++){try{const decoded=decodeURIComponent(text);if(decoded===text)break;text=decoded;}catch{break;}}return text;}
const money=n=>Number.isFinite(n)?formatMoney(n)+' gold':'N/A';
export const fleetColumns=[['Ship','id'],['Faction','faction'],['Class','type'],['Profit / hour','profitPerHour'],['Total profit','profit'],['Cargo','cargo'],['Capacity','cargoCapacity'],['Max speed','maxSpeed'],['Status','state']];
export function sortFleet(ships,key,descending=false){return [...ships].sort((a,b)=>{const av=a[key],bv=b[key];const result=typeof av==='number'&&typeof bv==='number'?av-bv:String(av??'').localeCompare(String(bv??''),undefined,{numeric:true});return(descending?-result:result)||String(a.id).localeCompare(String(b.id),undefined,{numeric:true});});}
export function waterIndicator(status){const fraction=Math.max(0,Math.min(1,status.fraction)),drops=Math.floor(fraction*5+1e-8),row=el('div');row.className='water-indicator';row.setAttribute('aria-label',`Water ${Math.round(fraction*100)}%, ${drops} of 5 drops`);for(let i=0;i<5;i++){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 16 22');svg.setAttribute('width','16');svg.setAttribute('height','22');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M8 1 C6 5 1 10 1 14 A7 7 0 0 0 15 14 C15 10 10 5 8 1 Z');path.setAttribute('fill',i<drops?'#53c9ff':'transparent');path.setAttribute('stroke','#53c9ff');svg.append(path);row.append(svg);}row.append(document.createTextNode(` ${Math.round(fraction*100)}%${status.stopping?' · Water stop':''}`));return row;}
export class ShipInspector {
 constructor({parent,getTraffic,getShips,onLocate=()=>{}}){Object.assign(this,{getTraffic,getShips,onLocate});this.selected=null;this.sortKey='profitPerHour';this.descending=true;
  this.panel=el('section');this.panel.className='ship-inspector';this.panel.hidden=true;this.panel.setAttribute('aria-label','Selected ship');this.title=el('h3');this.info=el('div');const close=el('button','Close');close.onclick=()=>this.select(null);this.more=el('button','More info');this.more.onclick=()=>this.open('ship');const locate=el('button','Find on map');locate.onclick=()=>{const ship=this.getShips().find(s=>s.id===this.selected);if(ship)this.onLocate(ship);};this.debug=el('button','Trade debug');this.debug.onclick=()=>this.open('debug');const actions=el('div');actions.className='inspector-actions';actions.append(this.more,this.debug,locate,close);this.panel.append(this.title,this.info,actions);parent.append(this.panel);
  this.dialog=el('dialog');this.dialog.className='bridge-dialog fleet-dialog';this.dialogTitle=el('h2');this.body=el('div');const done=el('button','Close');done.onclick=()=>this.dialog.close();this.dialog.append(this.dialogTitle,done,this.body);document.body.append(this.dialog);
  window.addEventListener('keydown',e=>{if(this.dialog.open){e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();this.dialog.close();}}else if(this.selected&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();this.select(null);}},{capture:true});
  this.dialog.addEventListener('close',()=>{this.mode=null;this.key=null;});this.dialog.addEventListener('keydown',e=>e.stopPropagation());
 }
 select(id){this.debugSnapshot=null;this.selected=id;this.panel.hidden=!id;this.panelKey=null;this.key=null;this.getTraffic()?.inspectShip(id);if(!id&&['ship','debug'].includes(this.mode))this.dialog.close();this.refresh();}
 reset(){this.select(null);this.dialog.close();this.mode=null;}
 open(mode){if(!this.getTraffic()?.worker||mode!=='fleet'&&!this.selected)return;this.mode=mode;this.key=null;this.debugSnapshot=null;this.refresh();if(!this.dialog.open)this.dialog.showModal();}
 table(headers,rows){const table=el('table'),head=el('tr');for(const h of headers)head.append(el('th',h));table.append(head);for(const values of rows){const tr=el('tr');for(const v of values)tr.append(el('td',v));table.append(tr);}return table;}
 refresh(){const traffic=this.getTraffic(),ships=this.getShips();if(!traffic?.worker){this.panel.hidden=true;if(this.dialog.open)this.dialog.close();return;}const ship=ships.find(s=>s.id===this.selected);
  if(this.selected&&!ship){this.select(null);return;}
  if(ship){const key=JSON.stringify(ship);if(key!==this.panelKey){this.panelKey=key;this.panel.hidden=false;this.title.replaceChildren(factionImage(ship.faction),document.createTextNode(shipTooltipLines(ship)[0]));this.info.replaceChildren();for(const line of shipTooltipLines(ship).slice(1))this.info.append(el('p',line));this.info.append(el('p',`Speed: ${(ship.speed??0).toFixed(2)} / ${(ship.maxSpeed??SHIP_TYPES[ship.type].maxSpeed).toFixed(2)}`));if(ship.waterStatus)this.info.append(waterIndicator(ship.waterStatus));if(!ship.player&&!ship.military)this.info.append(el('p',`Realised profit: ${money(ship.profit)} · ${ship.completedVoyages??0} voyages`));}}
  if(!this.mode||!this.dialog.open&&this.key!==null)return;if(this.mode==='debug'&&this.debugSnapshot)return;const details=traffic.shipDetails?.id===this.selected?traffic.shipDetails:null,key=JSON.stringify([this.mode,this.sortKey,this.descending,this.mode==='fleet'?ships.map(s=>fleetColumns.map(([,k])=>s[k])):[ship?.id,details]]);if(key===this.key)return;this.key=key;this.body.replaceChildren();
  if(this.mode==='fleet'){this.dialogTitle.textContent='Active ships';this.body.append(el('p',`${ships.length} active ships. Profit per hour uses realised voyage profit after purchases and sea-time running costs, per simulated hour. Military and player vessels do not trade.`));const table=el('table'),thead=el('thead'),row=el('tr');for(const [label,k] of fleetColumns){const th=el('th'),button=el('button',label+(k===this.sortKey?(this.descending?' ↓':' ↑'):''));th.setAttribute('aria-sort',k===this.sortKey?(this.descending?'descending':'ascending'):'none');button.onclick=()=>{this.descending=k===this.sortKey?!this.descending:['profitPerHour','profit','cargo','cargoCapacity','maxSpeed'].includes(k);this.sortKey=k;this.key=null;this.refresh();};th.append(button);row.append(th);}thead.append(row);table.append(thead);const tbody=el('tbody');for(const s of sortFleet(ships,this.sortKey,this.descending)){const tr=el('tr');for(const [,k] of fleetColumns){const td=el('td');if(k==='id'){const b=el('button',s.player?'Your ship':s.id);b.onclick=()=>{this.dialog.close();this.select(s.id);this.onLocate(s);};td.append(b);}else if(k==='faction')td.append(factionImage(s.faction));else if(k==='type')td.textContent=SHIP_TYPES[s.type].name;else if(k==='profit'||k==='profitPerHour')td.textContent=s.military||s.player?'N/A':money(s[k]);else td.textContent=typeof s[k]==='number'?supplyUnits(s[k]):String(s[k]??'').toLowerCase().replaceAll('_',' ');tr.append(td);}tbody.append(tr);}table.append(tbody);this.body.append(table);return;}
  this.dialogTitle.textContent=ship?SHIP_TYPES[ship.type].name+' · '+ship.id:'Ship details';if(!details){this.body.append(el('p','Loading ship records…'));return;}
  if(this.mode==='debug'){
   this.dialogTitle.textContent='Trade debug · '+ship.id;this.debugSnapshot=tradeDebugReport(ship,details,traffic.getWorld());
   this.body.append(el('p','Purchases and sales lock their actual price and settle payment when accepted at the dock. Timed handling moves paid goods without another payment. Trade is untaxed; eligible factory sales share proceeds with their parent town. Copy this snapshot to report a trade.'));
   const copy=el('button','Copy trade details'),refresh=el('button','Refresh snapshot'),report=el('textarea');report.readOnly=true;report.value=this.debugSnapshot;report.setAttribute('aria-label','Trade debug report');report.style.width='100%';report.style.height='55vh';report.style.fontFamily='monospace';
   copy.onclick=async()=>{try{await navigator.clipboard.writeText(report.value);copy.textContent='Copied';}catch{report.focus();report.select();copy.textContent='Select and copy the report';}};refresh.onclick=()=>{this.debugSnapshot=null;this.key=null;this.refresh();};this.body.append(copy,refresh,report);return;
  }
  if(details.runningCosts){const c=details.runningCosts,f=details.financialAccounts;this.body.append(el('h3','Sea-time running costs'),el('p',`Sailors purse: ${money(f?.sailors?.balance)} · Maintenance purse: ${money(f?.maintenance?.balance)}. Reserved for the next dock and unavailable for purchases.`),el('p',`Funded running costs: ${money(c.fundedSailors+c.fundedMaintenance)} · Settled at ports: ${money(c.settledGold)} · Unfunded shortfall: ${money(c.unfundedSailors+c.unfundedMaintenance)}. Shortfalls are diagnostic amounts, not payable debt.`));}
  if(details.water){this.body.append(el('h3','Provisions'),waterIndicator(details.water),el('p',`Morale: ${Math.round(details.morale)}%`));}
  if(details.navigation){const n=details.navigation;this.body.append(el('h3','Navigation telemetry'),el('p',`Mode: ${n.mode.toLowerCase().replaceAll('_',' ')} · ${n.probeTicks} five-probe checks · ${n.evasions} evasions · ${n.reversePivots} reverse/pivots · ${n.routeReplans} route recalculations · ${n.guardInterventions} swept-hull interventions · ${n.guidedInterventions} harbor safety interventions · ${n.unsafePoses} unsafe hull poses`));}
  if(details.trade?.pendingTransfers?.length)this.body.append(el('h3','Paid cargo awaiting handling'),this.table(['Goods','Operation','Owner','Location','Units remaining'],details.trade.pendingTransfers.map(t=>[commodityName(t.commodityId),t.kind==='PICKUP'?'Loading':'Unloading',readableEconomicId(t.ownerAccountId),readableEconomicId(t.remainingLocation),supplyUnits(t.remainingQuantity)])),el('p','Payment and ownership are settled. Goods become usable as each batch reaches its receiving store. Paid pickups remain reserved ashore until loaded.'));
  if(details.trade?.inventory){const inventory=details.trade.inventory;this.body.append(el('h3','Unsold merchant-owned cargo'),this.table(['Goods','Owner','Location','Units','Acquisition cost'],inventory.unsold.map(r=>[commodityName(r.commodityId),readableEconomicId(r.ownerAccountId),readableEconomicId(r.location),supplyUnits(r.quantity),money(r.acquisitionCost)])),el('h3','Paid deliveries aboard'),this.table(['Transfer','Buyer','Receiving store','Units remaining'],inventory.deliveries.map(t=>[readableEconomicId(t.id),readableEconomicId(t.ownerAccountId),readableEconomicId(t.destination),supplyUnits(t.remainingQuantity)])),el('h3','Paid pickups ashore'),this.table(['Transfer','Owner','Location','Units remaining'],inventory.pickups.map(t=>[readableEconomicId(t.id),readableEconomicId(t.ownerAccountId),readableEconomicId(t.remainingLocation),supplyUnits(t.remainingQuantity)])),el('h3','Completed physical transfers'),this.table(['Transfer','Operation','Owner','Destination','Units'],inventory.completed.map(t=>[readableEconomicId(t.id),t.kind,readableEconomicId(t.ownerAccountId),readableEconomicId(t.destination),supplyUnits(t.handledQuantity)])));}
  if(details.trade?.losses?.length)this.body.append(el('h3','Dumped cargo losses'),this.table(['Goods','Units','Acquisition cost','Tick'],details.trade.losses.map(r=>[commodityName(r.commodityId),supplyUnits(r.quantity),money(r.acquisitionCost),r.tick])));
  const journal=details.voyages;this.body.append(el('h3','Voyage history'),el('p',`${journal.completed} completed voyages · realised profit ${money(journal.realisedProfit)}. Showing the latest 100. Profit includes purchase cost and funded sea-time running costs; unsold cargo earns no proceeds.`));
  if(journal.current)this.body.append(el('p',`Current voyage: ${this.portName(journal.current.origin)} → ${this.portName(journal.current.destination)} · started at tick ${journal.current.startTick} · purchases ${money(journal.current.purchases)} · sales ${money(journal.current.revenue)}`));
  if(!journal.history.length)this.body.append(el('p',ship.player?'No automated trading voyages for the player ship.':'No completed voyages yet.'));else this.body.append(this.table(['Origin','Destination','Ticks','Cargo loaded / delivered','Purchases','Sales','Running costs','Profit'],journal.history.map(v=>[this.portName(v.origin),this.portName(v.destination),`${v.startTick}–${v.endTick}`,Object.entries(v.cargo).map(([c,q])=>`${commodityName(c)} ${supplyUnits(q.loaded)} / ${supplyUnits(q.delivered)}`).join(', ')||'None',money(v.purchases),money(v.revenue),money(v.maintenance),money(v.profit)])));
  this.body.append(el('h3','Current price ledger'),el('p',`Knowledge at tick ${details.tick}. Reports retain their original observation time.`));if(!details.ledger.length)this.body.append(el('p','No market knowledge yet. Dock to exchange reports.'));for(const entry of details.ledger){const block=el('section');block.className=entry.confidence<=.25?'ledger-stale':entry.confidence<=.5?'ledger-aging':'';block.append(el('h4',entry.portName),el('p',`Age ${entry.age} ticks · ${Math.round(entry.confidence*100)}% confidence · source ${this.portName(entry.originPortId)}`),this.table(['Goods','Supply asks: quantity @ price (seller)','Funded bids: quantity @ price (buyer)'],Object.entries(entry.prices).map(([c,p])=>[commodityName(c),formatMarketDepth(p.offers,'ask'),formatMarketDepth(p.orders,'bid')])));this.body.append(block);}
 }
 portName(id){return this.getTraffic()?.getWorld()?.ports.find(p=>p.id===id)?.name??id??'Unassigned';}
}
